/**
 * Semilla de ESTRUCTURAS DE CUENTAS (Ejercicio 2026) — replica la hoja GENERAL
 * del Excel que comparte Contaduría ('ESTRUCTURAS EJERCICIO 2026').
 * Cada fila es una razón social (FRENTE, RB, FLUJOS o SOFOM) con:
 *  - giro y núcleo de frentes (agrupadores del negocio),
 *  - importe máximo para bajar por mes y observaciones,
 *  - bancos donde tiene cuenta (JS, BANORTE, SANTANDER, … TRAFALGAR),
 *  - trámites/registros (SUCURSAL, REPSE, INE, CFE, ISN, …).
 * Contaduría mantiene este catálogo; se siembra sólo si la tabla está vacía.
 */

